<?php require_once __DIR__.'/includes/auth.php';require_admin();if(!hash_equals($_SESSION['csrf']??'',$_GET['csrf']??''))exit('Invalid request.');$id=(int)($_GET['id']??0);if($id){$st=db()->prepare('SELECT COUNT(*) FROM blogs WHERE category_id=?');$st->execute([$id]);if((int)$st->fetchColumn()>0){flash('warning','Category cannot be deleted while blogs are assigned to it.');}else{$pdo=db();$pdo->prepare('DELETE FROM blog_categories WHERE id=?')->execute([$id]);flash('success','Category deleted successfully.');}}redirect('categories.php');
